+  const fields = expression.trim().split(/\s+/);
+  if (fields.length !== 5) {
+    return CUSTOM;
+  }
+  const [minuteField, hourField, dayField, monthField, weekdayField] = fields;
+  if (monthField !== '*') {
+    return CUSTOM;
+  }
+  const everyDay = weekdayField === '*';
+  const weekdaysOnly = weekdayField === '1-5';
