+            <span>{t('Control all your apps and data from')}</span>
+            <ClientRotator />
+          </h1>
+        }
+      >
+        <div className="grid w-full grid-cols-1 items-start gap-6 lg:grid-cols-2">
+          <div className="flex flex-col gap-6">
